sys_script_include.script:
var ProductEvalUtils = Class.create();
ProductEvalUtils.prototype = {
    initialize: function() {},
    refQualProduct: function() {
        var evaluatedProducts = [];
        var availableProducts = [];
        var evaluationCounts = {};

//////// STRY 14 ////////

        // 1 - Busca os produtos avaliados pelo user
        var gr = new GlideRecord('x_2319535_jsf_pr_0_evaluation');
        gr.addQuery('opened_by', gs.getUserID());
        gr.addQuery('state', '!=', 4);
        gr.query();

        while (gr.next()) {
            evaluatedProducts.push(gr.getValue('product'));
        }

        // 2 - Filtra os que não foram avaliados pelo user
        var product = new GlideRecord('x_2319535_jsf_pr_0_product');
        product.addQuery('sys_id', 'NOT IN', evaluatedProducts.join(','));
        product.query();

//////// STRY 20 ////////

        // 3 - Conta as avaliações por produto
        var evaluation = new GlideAggregate('x_2319535_jsf_pr_0_evaluation');
        evaluation.addAggregate('COUNT');
        evaluation.groupBy('product');
        evaluation.query();

        while (evaluation.next()) {
            var productId = evaluation.getValue('product');
            var count = parseInt(evaluation.getAggregate('COUNT'));

            evaluationCounts[productId] = count;
        }

        // 4 - Filtra os produtos
        while (product.next()) {
            var currentProduct = product.getUniqueValue();
            var count = evaluationCounts[currentProduct] || 0;

            if (count < 5) {
                availableProducts.push(currentProduct);
            }
        }

        // 5 - Recupera os registros na lista de availableProducts
        return 'sys_idIN' + availableProducts.join(',');
    },
    type: 'ProductEvalUtils'
};
